-- Generated by medallion from spec/tables/gold_customer_value.toml. Do not edit by hand.
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.gold.customer_value (
  customer_id STRING COMMENT 'Customer identifier',
  email STRING COMMENT 'Current customer email address' MASK ${catalog}.governance.mask_email,
  orders_count BIGINT COMMENT 'Completed orders',
  lifetime_value DECIMAL(18,2) COMMENT 'Sum of completed order totals',
  first_order_date DATE COMMENT 'Date of the first completed order',
  last_order_date DATE COMMENT 'Date of the latest completed order'
)
COMMENT 'Lifetime value and order history per current customer. Email is masked for readers outside the privileged group.'
TBLPROPERTIES (
  'governance.owner' = 'customer-data',
  'governance.domain' = 'customer',
  'governance.classification' = 'confidential',
  'governance.spec' = 'spec/tables/gold_customer_value.toml',
  'governance.grain' = 'customer_id'
)
AS SELECT
  CAST(o.customer_id AS STRING) AS customer_id,
  CAST(max(c.email) AS STRING) AS email,
  CAST(count(*) AS BIGINT) AS orders_count,
  CAST(sum(o.amount) AS DECIMAL(18,2)) AS lifetime_value,
  CAST(min(to_date(o.order_ts)) AS DATE) AS first_order_date,
  CAST(max(to_date(o.order_ts)) AS DATE) AS last_order_date
FROM ${catalog}.silver.orders AS o
INNER JOIN ${catalog}.silver.customers AS c ON o.customer_id = c.customer_id AND c.__END_AT IS NULL
WHERE o.status = 'completed'
GROUP BY o.customer_id;
